FeatureDefinition.Code:
public string Get_Feature_MetryczkaNazwaKlienta(Context cx) {
    // Pole metryczki = węzeł konfiguracji A1Testy → Metryczka klienta → <klucz>, wartość w atrybucie "Wartosc".
    // Klucz nie zmienia się przy zmianie nazwy pola w Opcjach.
    Soneta.Config.CfgNode pole = new Soneta.Config.CfgManager(Row.Session).Root
        ?.FindSubNode("A1Testy", false)?.FindSubNode("Metryczka klienta", false)?.FindSubNode("NazwaKlienta", false);
    return pole?.FindAttribute("Wartosc", false)?.Value as string ?? "";
}
